reserved_word:
-- Quote the name with double quotes wherever it is used:
SELECT "{word}" FROM ...;
-- or rename it once:
ALTER TABLE {table} RENAME COLUMN "{word}" TO {word}_value;

fk_has_children:
-- Then choose: remove/move those rows first, or let the relation decide:
ALTER TABLE {child} DROP CONSTRAINT {constraint};
ALTER TABLE {child} ADD CONSTRAINT {constraint} FOREIGN KEY (<column>) REFERENCES {table}({parent_column}) ON DELETE CASCADE;  -- or ON DELETE SET NULL

disk_full:
-- How big is pg_wal, and why is it kept? (WAL kept for a slot or a failing archive can't be removed by PostgreSQL)
SELECT count(*) AS files, pg_size_pretty(sum(size)) AS total FROM pg_ls_waldir();
SELECT last_failed_wal, last_failed_time, last_archived_time FROM pg_stat_archiver;

host_not_allowed:
-- In pg_hba.conf allow just the app server, then reload:
host  {db}  {user}  {host}/32  scram-sha-256
SELECT pg_reload_conf();

replica_lag:
-- On the standby:
SELECT pg_is_in_recovery(), now() - pg_last_xact_replay_timestamp() AS replay_delay;
-- (when the primary is idle this number grows even though nothing is wrong: there is simply nothing new to replay)

source_log_purged:
-- Prevent: give the standby a physical replication slot (primary_slot_name), and cap what slots may keep:
SELECT slot_name, active, wal_status, pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS kept FROM pg_replication_slots;
-- max_slot_wal_keep_size protects the disk; wal_keep_size keeps extra WAL even without slots.

wal_retained_by_slot:
SELECT slot_name, slot_type, active, wal_status,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS wal_kept
FROM pg_replication_slots ORDER BY pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn) DESC NULLS LAST;

-- A slot with active = false whose standby / CDC tool no longer exists: drop it (the consumer then can't resume and must be rebuilt):
SELECT pg_drop_replication_slot('<slot name>');
CHECKPOINT;   -- old WAL is removed at the next checkpoint

checkpoints_too_frequent:
SHOW max_wal_size; SHOW checkpoint_timeout;
-- PostgreSQL 17+: SELECT num_timed, num_requested FROM pg_stat_checkpointer;
-- PostgreSQL 16 and older: SELECT checkpoints_timed, checkpoints_req FROM pg_stat_bgwriter;   -- many 'requested' = max_wal_size too small
